#!/bin/bash
# Task 178-w24-sortrefs -- meshsim sim/ WORKER24 (branch sim-w24; P6, inventory D1-D10).
# P6's references from v1.3, too long for the container: (1) SortFp's two BT runs (forced, 64 x 16,384 trace hot 10 /
# 10 %, kv32 and k128, ready 8; a state fingerprint at every GO and all-READY) through oracle/ref/sortfp.sh, in sim/ref;
# (2) v1.3's measurement kit assembled from sim/ref by oracle/ref/sortkit.sh (v1.3's kit/assemble.sh with F2's two
# fixes: v1.3's image files, sw/bootrom.hex) and run at -n 2000: all 92 runs. Needs a JDK. Not timing; the machine is
# recorded (D21). From an embedded kit. Writes only results/178-w24-sortrefs/. Scratch in /tmp, removed first and at
# the end. Safe to re-run from the start.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/178-w24-sortrefs; mkdir -p "$RES"
W=/tmp/w24-178; rm -rf "$W"; mkdir -p "$W"
trap 'rm -rf "$W"' EXIT
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "ca767af5153709d256b25f8b411fad3022637b6085597aa3e392134dd0cb2ec5" ] || { echo "kit sha256 mismatch (want ca767af5153709d256b25f8b411fad3022637b6085597aa3e392134dd0cb2ec5)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
(cd "$W/kit" && sha256sum -c --quiet HASHES) || { echo "kit files differ from HASHES"; exit 2; }
KS=$W/kit/sim
FAIL=0
verdict() { echo "VERDICT $1: $2"; echo "$1 $2" >> "$RES/VERDICTS"; [ "$2" = PASS ] || FAIL=1; }
: > "$RES/VERDICTS"
{ echo "kit: $(cat $W/kit/VERSION); host $(hostname); $(nproc) CPUs"; lscpu | grep -E '^(Model name|Thread|Core|Socket|CPU max MHz)'
  grep MemTotal /proc/meminfo; java -version 2>&1 | head -1; } | tee "$RES/machine.txt"
NP=$(nproc); J=$(( NP > 3 ? NP - 2 : 1 ))
# (1) the two BT runs, side by side, beside the kit
( P=2 KEEP="$W/fpfull" bash "$KS/oracle/ref/sortfp.sh" --fixtures '^bt16k' > "$RES/sortfp.out" 2>&1 ) & fpp=$!
# (2) the kit at 64 x 2,000, J at a time
( bash "$KS/oracle/ref/sortkit.sh" "$W/k" -n 2000 -j $J -m 2g > "$RES/sortkit.out" 2>&1 ) & kp=$!
wait $fpp; rc=$?; cat "$RES/sortfp.out"
mkdir -p "$RES/fp"; cp "$KS"/tests/sort/fp/bt16k-* "$KS/tests/sort/fp/HASHES" "$RES/fp/" 2>/dev/null
for f in "$W"/fpfull/*.fp; do [ -f "$f" ] && gzip -9n < "$f" > "$RES/fp/$(basename "$f").gz"; done
[ $rc = 0 ] && [ $(grep -c ': verify: .*PASS' "$RES/sortfp.out") = 2 ] && verdict bt-fp PASS || verdict bt-fp FAIL
wait $kp; rc=$?; tail -5 "$RES/sortkit.out"
if [ -d "$W/k/kit/results" ]; then
  (cd "$W/k/kit" && tar --sort=name --mtime=@0 --owner=0 --group=0 -czf "$RES/kit-n2000.tgz" results HASHES)
  cp "$W/k/kit/results/SUMMARY.md" "$W/k/kit/results/all.csv" "$W/k/kit/HASHES" "$RES/" 2>/dev/null
fi
n=$(ls "$W"/k/kit/results/*.csv 2>/dev/null | grep -v -e phases -e all.csv | wc -l)
bad=$(grep -L 'SortTest.*: [0-9]* passed, 0 failed' "$W"/k/kit/results/*.log 2>/dev/null | wc -l)
echo "kit: $n run CSVs, $bad logs without a clean pass"
[ $rc = 0 ] && [ "$n" = 92 ] && [ "$bad" = 0 ] && verdict kit-n2000 PASS || verdict kit-n2000 FAIL
(cd "$RES" && sha256sum $(find . -type f ! -name SHA256SUMS | sort) > SHA256SUMS)
echo; cat "$RES/VERDICTS"
[ $FAIL = 0 ] && { echo DONE; exit 0; } || { echo FAILED; exit 1; }
